  "packet_id": "H6-T04-2",
  "claim_id": "C039",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C039.main",
    "value": "A publication difference can support an effect of the change when random assignment is valid, follow-up is comparable and outcome capture is reliable.",
    "scope": "Conditional causal support, not guaranteed causal certainty or a report that these conditions hold.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P026",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P020 states the conditional causal inference. P026–P027 bound its interpretation when evidence is sparse or validity checks fail."
    }
  },
  "signal_basis": {
    "component_id": "C039.signal_basis",
    "value": "Compare the proportion of eligible accounts reaching a traceable first publication under the change versus the current flow, using valid random assignment, comparable follow-up and reliable outcome capture.",
    "scope": "The predefined observation window covers intended roster opportunities. The publication difference is assumed observed for this judgment; the mapping reports no completed findings. Linkage and capture comparability must be verified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
